function _b64ToUint8(base64)
{
	var binary_string = atob(base64);
	var len = binary_string.length;
	var bytes = new Uint8Array(len);
	for (var i = 0; i < len; i++) bytes[i] = binary_string.charCodeAt(i);
	return bytes;
}

function _allocArray(typedArray)
{
	var numBytes = typedArray.length * typedArray.BYTES_PER_ELEMENT;
	var ptr = CMPDF._malloc(numBytes);
	var heapBytes = new Uint8Array(CMPDF.HEAPU8.buffer, ptr, numBytes);
	heapBytes.set(new Uint8Array(typedArray.buffer));
	return heapBytes;
}

function _freeArray(heapBytes)
{
	CMPDF._free(heapBytes.byteOffset);
}

function _getStringVal(buf, len)
{
	var str = "", code;
	for(var i=0; i<len; i++)
	{
		if((code = CM_PDFGV(buf+i, "i8"))==0) break;
		str += String.fromCharCode(code);
	}
	return (i==0)?null:str;
}

function CM_PDFVerify(pdfAB, sCB, eCB)
{
	var pdfbuf = new Uint8Array(pdfAB, 0, pdfAB.byteLength);
	var pdf = CMPDF._malloc(pdfAB.byteLength);
	CMPDF.HEAPU8.set(pdfbuf, pdf);
	
	var passbuf = new Uint8Array(8);
	var pass = CMPDF._malloc(passbuf.length * passbuf.BYTES_PER_ELEMENT);
	CMPDF.setValue(pass, 0, "i8*");	//NULL set
	
	var sigmarkbuf = new Uint32Array(1);
	var sigmark = CMPDF._malloc(sigmarkbuf.length * sigmarkbuf.BYTES_PER_ELEMENT);
	CMPDF.setValue(sigmark, 0, "i32");	//NULL set
	
	var sigmarklenbuf = new Uint32Array(1);
	var sigmarklen = CMPDF._malloc(sigmarklenbuf.length * sigmarklenbuf.BYTES_PER_ELEMENT);
	CMPDF.setValue(sigmarklen, 0, "i32");	//NULL set
	
	var i, count, len, ptr, sm=null;
	count = jsPDFVerifyInit(pdf, pdfAB.byteLength, pass, 0, 0);
	if(count < 0)
	{
		eCB("Not a valid PDF document");
	}
	else if(count == 0)
	{
		if(jsPDFSigmarkLoad(0, pdf, pdfAB.byteLength, 0, sigmark, sigmarklen) == 0)
		{
			len = CMPDF.getValue(sigmarklen, "i32");
			if(len > 0)
			{
				ptr = CMPDF.getValue(sigmark, "i32");
				if(ptr > 0)
				{
					sm = _getStringVal(ptr, len);
					CMPDF._free(ptr);
				}
			}
			jsPDFSigmarkDestroy();
		}
		sCB([], sm);
	}
	else
	{
		var statusbuf = new Uint8Array(16);
		var status = CMPDF._malloc(statusbuf.length * statusbuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(statusbuf, status);
		
		var typebuf = new Uint8Array(16);
		var type = CMPDF._malloc(typebuf.length * typebuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(typebuf, type);
		
		var handlebuf = new Uint8Array(128);
		var handle = CMPDF._malloc(handlebuf.length * handlebuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(handlebuf, handle);
		
		var namebuf = new Uint8Array(1024);
		var name = CMPDF._malloc(namebuf.length * namebuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(namebuf, name);
		
		var timebuf = new Uint32Array(1);
		var time = CMPDF._malloc(timebuf.length * timebuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(timebuf, time);
		
		var vidbuf = new Uint32Array(1);
		var vid = CMPDF._malloc(vidbuf.length * vidbuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(vidbuf, vid);
		
		var eidbuf = new Uint32Array(1);
		var eid = CMPDF._malloc(eidbuf.length * eidbuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(eidbuf, eid);
		
		var certbuf = new Uint32Array(1);
		var cert = CMPDF._malloc(certbuf.length * certbuf.BYTES_PER_ELEMENT);
		
		var certlenbuf = new Uint32Array(1);
		var certlen = CMPDF._malloc(certlenbuf.length * certlenbuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(certlenbuf, certlen);
		
		var keybuf = new Uint8Array(512);
		var key = CMPDF._malloc(keybuf.length * keybuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(keybuf, key);
		
		var keyalgmbuf = new Uint8Array(16);
		var keyalgm = CMPDF._malloc(keyalgmbuf.length * keyalgmbuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(keyalgmbuf, keyalgm);
		
		var sigfieldnamebuf = new Uint8Array(64);
		var sigfieldname = CMPDF._malloc(sigfieldnamebuf.length * sigfieldnamebuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(sigfieldnamebuf, sigfieldname);
		
		var tamperbuf = new Uint32Array(1);
		var tamper = CMPDF._malloc(tamperbuf.length * tamperbuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(tamperbuf, tamper);
		
		var invisiblebuf = new Uint32Array(1);
		var invisible = CMPDF._malloc(invisiblebuf.length * invisiblebuf.BYTES_PER_ELEMENT);
		CMPDF.HEAPU8.set(invisiblebuf, invisible);
	
		var msg = [], rv, tmp, cert, ptr, j;
		for(i=0; i<count; i++)
		{
			rv = {};
			if(jsPDFVerifyGetSigner(i, status, type, handle, name, time, vid, eid, cert, certlen, key, keyalgm, sigfieldname, tamper, invisible) != 0)
			{
				rv.status = "bad";
				msg.push(rv);
				continue;
			}
			rv.status = _getStringVal(status, statusbuf.length * statusbuf.BYTES_PER_ELEMENT);
			rv.sigfieldname = _getStringVal(sigfieldname, sigfieldnamebuf.length * sigfieldnamebuf.BYTES_PER_ELEMENT);
			rv.type = _getStringVal(type, typebuf.length * typebuf.BYTES_PER_ELEMENT);
			rv.invisible = (CM_PDFGV(invisible, "i32")==1)?true:false;
			if((tmp = CM_PDFGV(time, "i32")) != 0) rv.signingTime = tmp;
			if((tmp = CM_PDFGV(certlen, "i32")) > 0)
			{
				rv.cert = new Uint8Array(tmp);
				ptr = CM_PDFGV(cert, "i32");
				if(ptr > 0)
				{
					//copy buffer from the pointer to pointer to Javascript buffer
					for(j=0; j<tmp; j++) rv.cert[j] = CM_PDFGV(ptr+j, "i8");
				}
			}
			
			if(rv.type == "key")
			{
				if((tmp = _getStringVal(handle, handlebuf.length * handlebuf.BYTES_PER_ELEMENT)) != null) rv.handle = tmp;
				if((tmp = _getStringVal(name, namebuf.length * namebuf.BYTES_PER_ELEMENT)) != null) rv.attestationSigner = tmp;
				if((tmp = _getStringVal(key, keybuf.length * keybuf.BYTES_PER_ELEMENT)) != null) rv.key = tmp;
				if((tmp = _getStringVal(keyalgm, keyalgmbuf.length * keyalgmbuf.BYTES_PER_ELEMENT)) != null) rv.keyAlgm = tmp;
				if((tmp = CM_PDFGV(vid, "i32")) > 0) rv.verifiedId = true;
				else rv.verifiedId = false;
				if((tmp = CM_PDFGV(eid, "i32")) > 0) rv.extendedId = true;
				else rv.extendedId = false;
				rv.signerTampered = (CM_PDFGV(tamper, "i32")==1)?true:false;
			}
			else
			{
				if((tmp = _getStringVal(handle, handlebuf.length * handlebuf.BYTES_PER_ELEMENT)) != null) rv.signerName = tmp;
			}
			msg.push(rv);
		}
		
		if(jsPDFSigmarkLoad(0, pdf, pdfAB.byteLength, 0, sigmark, sigmarklen) == 0)
		{
			len = CMPDF.getValue(sigmarklen, "i32");
			if(len > 0)
			{
				ptr = CMPDF.getValue(sigmark, "i32");
				if(ptr > 0)
				{
					sm = _getStringVal(ptr, len);
					CMPDF._free(ptr);
				}
			}
			jsPDFSigmarkDestroy();
		}
		
		jsPDFVerifyDestroy();
		CMPDF._free(invisible);
		CMPDF._free(tamper);
		CMPDF._free(sigfieldname);
		CMPDF._free(keyalgm);
		CMPDF._free(key);
		CMPDF._free(certlen);
		CMPDF._free(cert);
		CMPDF._free(eid);
		CMPDF._free(vid);
		CMPDF._free(time);
		CMPDF._free(name);
		CMPDF._free(handle);
		CMPDF._free(type);
		CMPDF._free(status);
		
		sCB(msg, sm);
	}
	
	CMPDF._free(sigmark);
	CMPDF._free(sigmarklen);
	CMPDF._free(pass);
	CMPDF._free(pdf);
}

function CM_PDFSetProfileV2(profile)
{
	var rv, i, mask, maskarr, img, buf, stream, altstream;
	
	var offset = (new Date()).getTimezoneOffset();
	var tz;
	if(offset < 0) tz = "+";
	else if(offset > 0) tz = "-";
	else tz = "";
	
	i = Math.trunc(Math.abs(offset/60))+"";
	if(i.length == 1) tz += "0";
	tz += i;
	i = Math.abs(offset%60)+"";
	if(i.length == 1) tz += "0";
	tz += i;
	jsSetTimezone(tz);
	
	if(profile.Version != 2)
	{
		console.log("PDF: Not a Version 2 signature profile");
		return 1;
	}
	else if(isNaN(profile.Page))
	{
		console.log("PDF: Page number information unavailable");
		return -1;
	}
	else if(profile.BoxDimensions == undefined || profile.BoxDimensions.width <=0 || profile.BoxDimensions.height <= 0)
	{
		console.log("PDF: Profile dimension unavailable or incorrect");
		return -1;
	}
	else if(profile.BoxPosition == undefined || profile.BoxPosition.x <0 || profile.BoxPosition.y < 0)
	{
		console.log("PDF: Profile position unavailable or incorrect");
		return -1;
	}
	
	if(profile.isdemo != undefined && profile.isdemo == true) jsSetDemo(1);
	else jsSetDemo(0);
	
	if((rv = jsSetPageNo2(profile.Page, profile.BoxPosition.x, profile.BoxPosition.y, profile.BoxDimensions.width, profile.BoxDimensions.height)) != 0)
	{
		console.log("PDF: Profile page number cannot be set: "+rv);
		return -2;
	}
	
	if(profile.Images != undefined)
	{
		i = 0;
		while(i < profile.Images.length)
		{
			if(profile.Images[i].Name == undefined || profile.Images[i].Buffer == undefined)
			{
				console.log("PDF: Profile signature image is unavailable or incorrect");
				return -1;
			}
			img = _b64ToUint8(profile.Images[i].Buffer);
			buf = CMPDF._malloc(img.byteLength);
			CMPDF.HEAPU8.set(img, buf);
			
			mask = null;
			maskarr = null;
			if(profile.Images[i].Mask != undefined)
			{
				mask = new Int32Array(profile.Images[i].Mask);
				maskarr = _allocArray(mask);
			}
			
			if((rv = jsSetSignatureImage2(buf, img.byteLength, profile.Images[i].Name, maskarr.byteOffset, (mask==null)?0:mask.length)) != 0)
			{
				console.log("PDF: Profile signature image "+profile.Images[i].Name+" cannot be set: "+rv);
				if(maskarr != null)
				{
					_freeArray(maskarr);
					maskarr = null;
					mask = null;
				}
				CMPDF._free(buf);
				return -2;
			}
			if(maskarr != null)
			{
				_freeArray(maskarr);
				maskarr = null;
				mask = null;
			}
			CMPDF._free(buf);	//can be cleared as a copy is made internally
			i++;
		}
	}
	
	if(profile.Fonts != undefined)
	{
		i = 0;
		while(i < profile.Fonts.length)
		{
			if(profile.Fonts[i].Name == undefined || profile.Fonts[i].FontName == undefined)
			{
				console.log("PDF: Profile signature font is unavailable or incorrect");
				return -1;
			}
			else if((rv = jsSetSignatureFont2(profile.Fonts[i].Name, profile.Fonts[i].FontName, null)))
			{
				console.log("PDF: Profile signature font "+profile.Fonts[i].Name+" cannot be set: "+rv);
				return -2;
			}
			i++;
		}
	}
	
	if(profile.Date != undefined)
	{
		i = 0;
		while(i < profile.Date.length)
		{
			if(profile.Date[i].Name == undefined || profile.Date[i].Format == undefined)
			{
				console.log("PDF: Profile signature date is unavailable or incorrect");
				return -1;
			}
			else if((rv = jsSetSignatureFont2(profile.Date[i].Name, "", profile.Date[i].Format)))
			{
				console.log("PDF: Profile signature date "+profile.Date[i].Name+" cannot be set: "+rv);
				return -2;
			}
			i++;
		}
	}
	
	if(profile.Stream == undefined)
	{
		console.log("PDF: Profile stream unavailable");
		return -1;
	}
	stream = atob(profile.Stream);
	if((rv = jsSetStream2(stream, stream.length)) != 0)
	{
		console.log("PDF: Profile stream cannot be set: "+rv);
		return -2;
	}
	
	if(profile.AlternateStream != undefined)
	{
		altstream = atob(profile.AlternateStream);
		if((rv = jsSetRolloverStream2(altstream, altstream.length)) != 0)
		{
			console.log("PDF: Profile alternate stream cannot be set: "+rv);
			return -2;
		}
	}
	
	CM_PDFSetProfileVersion(profile.Version);
	return 0;
}

function CM_PDFSetSignaturePage(flag, pagenum, x, y, width, height, rotation, bwidth, bheight, cropArr)
{
	var ca = new Int32Array(cropArr);
	var crop = _allocArray(ca);
	var rv = jsSetPageNo(flag, pagenum, x, y, width, height, crop.byteOffset, bwidth, bheight, rotation);
	_freeArray(crop);
	return rv;
}

function CM_PDFSetSignatureText(str, x, y, fontname, fontsize, fontcolor)
{
	var color = [];
	color.push(fontcolor.R);
	color.push(fontcolor.G);
	color.push(fontcolor.B);
	
	var typedArray = new Int32Array(color);
	var numBytes = typedArray.length * typedArray.BYTES_PER_ELEMENT;
	var ptr = CMPDF._malloc(numBytes);
	var heapBytes = new Uint8Array(CMPDF.HEAPU8.buffer, ptr, numBytes);
	heapBytes.set(new Uint8Array(typedArray.buffer));

	var rv = jsSetSignatureText(str, x, y, fontname, fontsize, heapBytes.byteOffset);
	CMPDF._free(ptr);
	
	return rv;
}

function CM_PDFSetSignatureImage(imageAB, x, y, width, height, mask)
{
	var data = new Uint8Array(imageAB, 0, imageAB.byteLength);
	var buf = CMPDF._malloc(imageAB.byteLength);
	CMPDF.HEAPU8.set(data, buf);
	
	var rv = jsSetSignatureImage(buf, imageAB.byteLength, x, y, width, height, mask);
	CMPDF._free(buf);
	
	return rv;
}

function CM_PDFKeySetSigner(handle, keyType, verifiedId, extendedId, proxyHandle, keyAB)
{
	var keybuf = new Uint8Array(keyAB, 0, keyAB.byteLength);
	var key = CMPDF._malloc(keyAB.byteLength);
	CMPDF.HEAPU8.set(keybuf, key);
	
	jsKeySignerSetAppname("ASBrowser");
	var rv = jsKeySignerAdd(handle, keyType, verifiedId.toString(), extendedId.toString(), key, keyAB.byteLength, proxyHandle);
	CMPDF._free(key);
	return rv;
}

function CM_PDFKeyAddSignature(sigAB, fullSigAB)
{
	var sigbuf = new Uint8Array(sigAB, 0, sigAB.byteLength);
	var sig = CMPDF._malloc(sigAB.byteLength);
	CMPDF.HEAPU8.set(sigbuf, sig);
	
	var newsigbuf = new Uint32Array(1);
	var newsig = CMPDF._malloc(newsigbuf.length * newsigbuf.BYTES_PER_ELEMENT);
	
	var newsiglenbuf = new Uint32Array(1);
	var newsiglen = CMPDF._malloc(newsiglenbuf.length * newsiglenbuf.BYTES_PER_ELEMENT);
	CMPDF.HEAPU8.set(newsiglenbuf, newsiglen);
	
	var rv, buf, len, ptr, i;
	
	if(fullSigAB == null)
	{
		CMPDF.setValue(newsig, 0, "i32");	//NULL set
		CMPDF.setValue(newsiglen, 0, "i32");	//set to ZERO
		rv = jsKeySignerAddSignature(newsig, newsiglen, sig, sigAB.byteLength);
	}
	else
	{
		var sig1buf = new Uint8Array(fullSigAB, 0, fullSigAB.byteLength);
		var sig1 = CMPDF._malloc(fullSigAB.byteLength);
		CMPDF.HEAPU8.set(sig1buf, sig1);
		
		CMPDF.setValue(newsig, sig1, "i8*");
		CMPDF.setValue(newsiglen, fullSigAB.byteLength, "i32");
		rv = jsKeySignerAddSignature(newsig, newsiglen, sig, sigAB.byteLength);
	}
	
	if(rv == 0)
	{
		len = CM_PDFGV(newsiglen, "i32");
		ptr = CMPDF.getValue(newsig, "i32");
		if(ptr > 0)
		{
			buf = new Uint8Array(len);
			//copy buffer from the pointer to pointer to Javascript buffer
			for(i=0; i<len; i++) buf[i] = CMPDF.getValue(ptr+i, "i8");
			CMPDF._free(ptr);
		}
		else
		{
			rv = -1;
		}
	}
	
	CMPDF._free(newsiglen);
	CMPDF._free(newsig);
	CMPDF._free(sig);
	return (rv!=0)?null:buf;
}

function CM_PDFAppendSigObjects(pdfAB, pdfPassword, digestType, signerName, legacyAppearance, sigmarkPos, isEPF, sigSize, sCB, eCB)
{
	var lenDigest = 32;
	var digestDefine = 121;
	
	if(legacyAppearance == true) CM_PDFUseLegacyAppearance(1);
	else CM_PDFUseLegacyAppearance(0);
	
	//set the local timezone for signing time
	var offset = (new Date()).getTimezoneOffset();
	var tz;
	if(offset < 0) tz = "+";
	else if(offset > 0) tz = "-";
	else tz = "";
	
	i = Math.trunc(Math.abs(offset/60))+"";
	if(i.length == 1) tz += "0";
	tz += i;
	tz += "'";
	i = Math.abs(offset%60)+"";
	if(i.length == 1) tz += "0";
	tz += i;
	tz += "'";
	jsSetTimezone_S(tz);
	//till here
	
	if(digestType == "sha1" || isEPF == true)
	{
		lenDigest = 20;
		digestDefine = 120;
	}
	//default is SHA2
	
	var data = new Uint8Array(pdfAB, 0, pdfAB.byteLength);
	var buf = CMPDF._malloc(pdfAB.byteLength);
	CMPDF.HEAPU8.set(data, buf);
	
	var bufsize = ((pdfAB.byteLength * 2) + (65536 * 2) + sigSize);	//calculate size of the PDF file to be generated
	var pdfbuf = new Uint8Array(bufsize);
	var pdf = CMPDF._malloc(bufsize);
	CMPDF.HEAPU8.set(pdfbuf, pdf);
	
	var pdflenbuf = new Uint32Array(1);
	var pdflen = CMPDF._malloc(pdflenbuf.length * pdflenbuf.BYTES_PER_ELEMENT);	//be careful when using Uint#Array where # > 8
	CM_PDFSV(pdflen, bufsize, "i32");
	
	//INFO: length of the digest has been set to 32 (max digset len) because this is handled in C source like this; TODO: Must be changed and the working should be verified
	var digestbuf = new Uint8Array(32);
	var digest = CMPDF._malloc(32);
	CMPDF.HEAPU8.set(digestbuf, digest);
	
	var sigposbuf = new Uint32Array(1);
	var sigpos = CMPDF._malloc(sigposbuf.length * sigposbuf.BYTES_PER_ELEMENT);	//be careful when using Uint#Array where # > 8
	CMPDF.HEAPU8.set(sigposbuf, sigpos);
	
	var errstrbuf = new Uint8Array(1024);
	var errstr = CMPDF._malloc(errstrbuf.length * errstrbuf.BYTES_PER_ELEMENT);
	CMPDF.HEAPU8.set(errstrbuf, errstr);
	
	if(sigmarkPos != null)
	{
		if(jsPDFSigmarkLoad(0, buf, pdfAB.byteLength, 0, 0, 0) == 0)
		{
			jsPDFSigmarkRemove(sigmarkPos.pageNo, sigmarkPos.position[0], sigmarkPos.position[1], sigmarkPos.label, errstr);
		}
	}
	
	var rv = CM_PDFSignPhase1WithType(buf, pdfAB.byteLength, pdfPassword, pdf, pdflen, digestDefine, signerName, (isEPF==true)?"Adobe.PPKMS":"Adobe.PPKLite", digest, sigpos);
	if(rv == 0)
	{
		if(sCB)
		{
			var i;
			var oPDFLen = CM_PDFGV(pdflen, "i32");
			var fPDF = new Uint8Array(oPDFLen);
			for(i=0; i<oPDFLen; i++) fPDF[i] = CM_PDFGV(pdf+i, "i8");
			var fDigest = new Uint8Array(lenDigest);
			for(i=0; i<lenDigest; i++) fDigest[i] = CM_PDFGV(digest+i, "i8");
			sCB(fPDF, fDigest, CM_PDFGV(sigpos, "i32"));
		}
	}
	else
	{
		if(eCB)
		{
			eCB(CM_PDFGetError(rv));
		}
	}
	
	if(sigmarkPos != null) jsPDFSigmarkDestroy();
	CMPDF._free(sigpos);
	CMPDF._free(digest);
	CMPDF._free(pdflen);
	CMPDF._free(pdf);
	CMPDF._free(buf);
	return rv;
}

function CM_PDFAppendEPFSigObjects(pdfAB, signerHandle, subjectCN, signDateTime, sigSize, sCB, eCB)
{
	//set the local timezone for signing time
	var offset = (new Date()).getTimezoneOffset();
	var tz;
	if(offset < 0) tz = "+";
	else if(offset > 0) tz = "-";
	else tz = "";
	
	i = Math.trunc(Math.abs(offset/60))+"";
	if(i.length == 1) tz += "0";
	tz += i;
	tz += "'";
	i = Math.abs(offset%60)+"";
	if(i.length == 1) tz += "0";
	tz += i;
	tz += "'";
	jsSetTimezone_S(tz);
	//till here
	
	var data = new Uint8Array(pdfAB, 0, pdfAB.byteLength);
	var buf = CMPDF._malloc(pdfAB.byteLength);
	CMPDF.HEAPU8.set(data, buf);
	
	var bufsize = ((pdfAB.byteLength * 2) + (65536 * 2) + sigSize);	//calculate size of the PDF file to be generated
	var pdfbuf = new Uint8Array(bufsize);
	var pdf = CMPDF._malloc(bufsize);
	CMPDF.HEAPU8.set(pdfbuf, pdf);
	
	var pdflenbuf = new Uint32Array(1);
	var pdflen = CMPDF._malloc(pdflenbuf.length * pdflenbuf.BYTES_PER_ELEMENT);	//be careful when using Uint#Array where # > 8
	CM_PDFSV(pdflen, bufsize, "i32");
	
	//INFO: length of the digest has been set to 20 (max digset len) because this is handled in C source like this; TODO: Must be changed and the working should be verified
	var digestbuf = new Uint8Array(20);
	var digest = CMPDF._malloc(20);
	CMPDF.HEAPU8.set(digestbuf, digest);
	
	var sigposbuf = new Uint32Array(1);
	var sigpos = CMPDF._malloc(sigposbuf.length * sigposbuf.BYTES_PER_ELEMENT);	//be careful when using Uint#Array where # > 8
	CMPDF.HEAPU8.set(sigposbuf, sigpos);
	
	var errstrbuf = new Uint8Array(1024);
	var errstr = CMPDF._malloc(errstrbuf.length * errstrbuf.BYTES_PER_ELEMENT);
	CMPDF.HEAPU8.set(errstrbuf, errstr);
	
	var rv = CM_PDFSignPhase1EPF(buf, pdfAB.byteLength, signerHandle, subjectCN, signDateTime, pdf, pdflen, digest, sigpos);
	if(rv == 0)
	{
		if(sCB)
		{
			var i;
			var oPDFLen = CM_PDFGV(pdflen, "i32");
			var fPDF = new Uint8Array(oPDFLen);
			for(i=0; i<oPDFLen; i++) fPDF[i] = CM_PDFGV(pdf+i, "i8");
			var fDigest = new Uint8Array(20);
			for(i=0; i<20; i++) fDigest[i] = CM_PDFGV(digest+i, "i8");
			sCB(fPDF, fDigest, CM_PDFGV(sigpos, "i32"));
		}
	}
	else
	{
		if(eCB)
		{
			eCB(CM_PDFGetError(rv));
		}
	}
	
	CMPDF._free(sigpos);
	CMPDF._free(digest);
	CMPDF._free(pdflen);
	CMPDF._free(pdf);
	CMPDF._free(buf);
	return rv;
}

function CM_PDFEmbedSig(pdfAB, sigAB, sigPos, sCB, eCB)
{
	var data = new Uint8Array(pdfAB, 0, pdfAB.byteLength);
	var pdf = CMPDF._malloc(pdfAB.byteLength);
	CMPDF.HEAPU8.set(data, pdf);
	
	var sigbuf = new Uint8Array(sigAB, 0, sigAB.byteLength);
	var signature = CMPDF._malloc(sigAB.byteLength);
	CMPDF.HEAPU8.set(sigbuf, signature);
	
	var rv = CM_PDFSignPhase2(pdf, pdfAB.byteLength, signature, sigAB.byteLength, sigPos);
	if(rv == 0)
	{
		if(sCB)
		{
			var finalPDF = new Uint8Array(pdfAB.byteLength);
			for(var i=0; i<pdfAB.byteLength; i++) finalPDF[i] = CM_PDFGV(pdf+i, "i8");
			sCB(finalPDF);
		}
	}
	else
	{
		if(eCB)
		{
			eCB(CM_PDFGetError(rv));
		}
	}
	
	CMPDF._free(signature);
	CMPDF._free(pdf);
	return rv;
}

function CM_PDFSigmark(pdfAB, sigmarks, rsm, sCB, eCB)
{
	var pdfbuf = new Uint8Array(pdfAB, 0, pdfAB.byteLength);
	var pdf = CMPDF._malloc(pdfAB.byteLength);
	CMPDF.HEAPU8.set(pdfbuf, pdf);
	
	var errstrbuf = new Uint8Array(1024);
	var errstr = CMPDF._malloc(errstrbuf.length * errstrbuf.BYTES_PER_ELEMENT);
	CMPDF.HEAPU8.set(errstrbuf, errstr);
	
	var sigmarkbuf = new Uint32Array(1);
	var sigmark = CMPDF._malloc(sigmarkbuf.length * sigmarkbuf.BYTES_PER_ELEMENT);
	CMPDF.setValue(sigmark, 0, "i32");	//NULL set
	
	var sigmarklenbuf = new Uint32Array(1);
	var sigmarklen = CMPDF._malloc(sigmarklenbuf.length * sigmarklenbuf.BYTES_PER_ELEMENT);
	CMPDF.setValue(sigmarklen, 0, "i32");	//NULL set
	
	var i, len, ptr, sm;
	
	jsPDFSigmarkLoad(0, pdf, pdfAB.byteLength, 0, 0, 0);
	for(i=0; i<rsm.length; i++)
	{
		jsPDFSigmarkRemove(rsm[i].pageNo, rsm[i].position[0], rsm[i].position[1], rsm[i].label, errstr);
	}
	
	for(i=0; i<sigmarks.length; i++)
	{
		if(jsPDFSigmarkAdd(sigmarks[i].pageNo, sigmarks[i].position[0], sigmarks[i].position[1], sigmarks[i].label, errstr) != 0)
		{
			break;
		}
	}
	if(i == sigmarks.length)
	{
		if(jsPDFSigmarkCompose(pdf, pdfAB.byteLength, sigmark, sigmarklen) == 0)
		{
			len = CMPDF.getValue(sigmarklen, "i32");
			if(len > 0)
			{
				ptr = CMPDF.getValue(sigmark, "i32");
				if(ptr > 0)
				{
					var sm = new Uint8Array(len);
					for(i=0; i<len; i++) sm[i] = CMPDF.getValue(ptr+i, "i8");
					CMPDF._free(ptr);
					sCB(sm);
				}
				else
				{
					eCB("Failed to create SigMark");
				}
			}
			else
			{
				eCB("Failed to create SigMark");
			}
		}
		else
		{
			eCB("Failed to create SigMark");
		}
	}
	else
	{
		eCB("Failed to create SigMark: Insufficient memory");
	}
	
	jsPDFSigmarkDestroy();
	CMPDF._free(sigmarklen);
	CMPDF._free(sigmark);
	CMPDF._free(errstr);
	CMPDF._free(pdf);
	return;
}

function CM_PDFGetError(errcode)
{
	switch(errcode)
	{
		case -1: return "Invalid PDF";
		case -2: return "PDF Encrypted";
		case -5: return "Insufficient Memory";
		case -9: return "Invalid PDF Signature";
		case -15: return "Password Missing";
		case -16: return "Invalid Password";
		case -17: return "Unsupported Encryption";
		case -18: return "PDF Incomplete";
		case -19: return "Invalid Parameter";
		case -22: return "PDF Not Encrypted";
		case -23: return "Inadequate Memory";
		case -2000: return "PDF page doesn't match the configured profile";
		default: return "Unknown Error : "+rv;
	}
}